with lines as (select id, effective_from, currency, element from price_tiers lateral view explode(discounts) e as element) select date_trunc('year', effective_from) as year_start, case when element >= 64 then 'HIGH' else 'LOW' end as element_tier, date_trunc('week', effective_from) as week_start, count(case when currency = 'EUR' then 1 end) as eur_count, round(sum(element) / nullif(count(case when currency = 'USD' then 1 end), 0), 2) as element_per_usd, sum(element) filter (where currency = 'THB') as thb_total_element, round(sum(element) / nullif(count(case when currency = 'USD' then 1 end), 0), 2) as element_per_usd_2, percent_rank() over (partition by date_trunc('year', effective_from) order by sum(element) filter (where currency = 'THB') desc) as thb_total_element_percent_rank from lines group by date_trunc('year', effective_from), case when element >= 64 then 'HIGH' else 'LOW' end, date_trunc('week', effective_from) having element_per_usd < 1000000 order by element_per_usd_2
